import java.io.*;import java.util.*;import com.android.tools.smali.dexlib2.*;import com.android.tools.smali.dexlib2.iface.*;import app.hiro.berry.patches.*;
public class ResolveNegative {
 static List<ClassDef> read(String path)throws Exception{List<ClassDef> c=new ArrayList<>();MultiDexContainer<? extends DexFile>d=DexFileFactory.loadDexContainer(new File(path),Opcodes.forApi(37));for(String n:d.getDexEntryNames())c.addAll(d.getEntry(n).getDexFile().getClasses());return c;}
 static void fails(String label,Runnable r){try{r.run();throw new AssertionError("Unresolved target incorrectly accepted: "+label);}catch(IllegalStateException expected){System.out.println("PASS "+label+": "+expected.getMessage());}}
 public static void main(String[] a)throws Exception{List<ClassDef> original=read(a[0]);fails("wrong package",()->GenericBerryResolver.resolve("wrong.package",original));List<ClassDef> missing=new ArrayList<>(original);missing.removeIf(c->c.getType().equals("Lcx;"));fails("missing webview",()->GenericBerryResolver.resolve("jp.ejimax.berrybrowser",missing));List<ClassDef> noPreview=new ArrayList<>(original);noPreview.removeIf(c->c.getType().equals("Lg60;"));BerryProfiles.Profile p=GenericBerryResolver.resolve("jp.ejimax.berrybrowser",noPreview);fails("missing preview",()->p.type("Lg60;"));List<ClassDef> both=new ArrayList<>(original);for(ClassDef c:read(a[1]))if(c.getType().startsWith("Lqa/renamed/"))both.add(c);fails("ambiguous compatible graphs",()->GenericBerryResolver.resolve("jp.ejimax.berrybrowser",both));}
}
